/* EASPhub Apple application alignment v1.1.
   Visual reference: brand/components/EASPhub-工作平台原型.html. */
:root {
  --ea-canvas: #F5F5F7;
  --ea-base: #FFFFFF;
  --ea-subtle: #EFEFF4;
  --ea-hover: rgba(120,120,128,.11);
  --ea-pressed: rgba(120,120,128,.2);
  --ea-ink: #1D1D1F;
  --ea-secondary: rgba(60,60,67,.74);
  --ea-muted: #6A6A78;
  --ea-border: rgba(60,60,67,.13);
  --ea-border-strong: rgba(60,60,67,.26);
  --ea-line: rgba(60,60,67,.1);
  --ea-action: #386EBD;
  --ea-action-hover: #2F5FA5;
  --ea-action-pressed: #284F8B;
  --ea-action-fg: #FFFFFF;
  --ea-action-soft: #F3F6FB;
  --ea-selection: #E9EFF8;
  --ea-success: #248A3D;
  --ea-warning: #A85800;
  --ea-danger: #D70015;
  --ea-success-soft: rgba(52,199,89,.14);
  --ea-warning-soft: rgba(255,149,0,.16);
  --ea-danger-soft: rgba(255,59,48,.13);
  --ea-shadow-card: 0 1px 2px rgba(0,0,0,.04),0 6px 20px rgba(0,0,0,.06);
  --ea-shadow-hover: 0 2px 5px rgba(0,0,0,.05),0 16px 40px rgba(0,0,0,.12);
  --ea-shadow-raise: 0 1px 3px rgba(0,0,0,.05),0 10px 28px rgba(0,0,0,.07);
  --ea-shadow-pop: 0 0 0 .5px rgba(0,0,0,.06),0 12px 44px rgba(0,0,0,.18);
  --ea-material-chrome: rgba(255,255,255,.74);
  --ea-material-sidebar: rgba(233,233,238,.8);
  --ea-grid-line: rgba(60,60,67,.035);
  --ea-radius-card: 16px;
  --ea-radius-control: 10px;
  --ea-radius-pill: 100px;
  --ea-ease: cubic-bezier(.32,.72,0,1);
  --ea-font: "EA Inter","EA Sarasa","Inter","Sarasa UI SC",-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei UI",system-ui,sans-serif;
  color-scheme: light;
  font-family: var(--ea-font);
  font-synthesis: none;
}
:root[data-ea-mode="dark"],:root[data-theme="dark"],html.easp-theme-dark {
  --ea-canvas: #000000;
  --ea-base: #1C1C1E;
  --ea-subtle: #2C2C2E;
  --ea-hover: rgba(120,120,128,.22);
  --ea-pressed: rgba(120,120,128,.34);
  --ea-ink: #FFFFFF;
  --ea-secondary: rgba(235,235,245,.62);
  --ea-muted: #A5A5B5;
  --ea-border: rgba(120,120,128,.34);
  --ea-border-strong: rgba(120,120,128,.58);
  --ea-line: rgba(120,120,128,.22);
  --ea-action: #9BBEF0;
  --ea-action-hover: #BAD1F6;
  --ea-action-pressed: #D3E1FA;
  --ea-action-fg: #232329;
  --ea-action-soft: #2D2F39;
  --ea-selection: #343945;
  --ea-success: #30D158;
  --ea-warning: #FFB340;
  --ea-danger: #FF6961;
  --ea-success-soft: rgba(48,209,88,.18);
  --ea-warning-soft: rgba(255,159,10,.18);
  --ea-danger-soft: rgba(255,69,58,.18);
  --ea-shadow-card: 0 0 0 .5px rgba(255,255,255,.07),0 4px 16px rgba(0,0,0,.5);
  --ea-shadow-hover: 0 0 0 .5px rgba(255,255,255,.13),0 14px 36px rgba(0,0,0,.62);
  --ea-shadow-raise: 0 0 0 .5px rgba(255,255,255,.08),0 10px 26px rgba(0,0,0,.52);
  --ea-shadow-pop: 0 0 0 .5px rgba(255,255,255,.1),0 16px 48px rgba(0,0,0,.72);
  --ea-material-chrome: rgba(28,28,30,.74);
  --ea-material-sidebar: rgba(28,28,30,.76);
  --ea-grid-line: rgba(235,235,245,.04);
  color-scheme: dark;
}
html { font-size: 100%; }
body {
  font-family: var(--ea-font);
  font-size: 14px;
  line-height: 1.5;
  letter-spacing: -.006em;
  color: var(--ea-ink);
  background: var(--ea-canvas);
  font-variant-numeric: tabular-nums;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
button,input,select,textarea { font-family: inherit; }
button,a { touch-action: manipulation; }
button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,
textarea:focus-visible,summary:focus-visible {
  outline: 3px solid color-mix(in srgb,var(--ea-action) 36%,transparent);
  outline-offset: 2px;
}
input,select,textarea {
  border: 1px solid var(--ea-border);
  border-radius: var(--ea-radius-control);
  background: var(--ea-base);
  color: var(--ea-ink);
  font-size: 14px;
  transition: border-color .18s var(--ea-ease),box-shadow .18s var(--ea-ease);
}
input:hover:not(:disabled),select:hover:not(:disabled),textarea:hover:not(:disabled) { border-color: var(--ea-border-strong); }
input:focus,select:focus,textarea:focus {
  border-color: var(--ea-action);
  box-shadow: 0 0 0 3.5px color-mix(in srgb,var(--ea-action) 36%,transparent);
}
::selection { background: color-mix(in srgb,var(--ea-action) 22%,transparent); }
.ea-topbar {
  position: sticky;
  top: 0;
  z-index: 70;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 56px;
  padding: 0 26px;
  border-bottom: 1px solid var(--ea-line);
  color: var(--ea-secondary);
  background: var(--ea-material-chrome);
  -webkit-backdrop-filter: blur(30px) saturate(180%);
  backdrop-filter: blur(30px) saturate(180%);
  font-size: 13px;
}
.ea-topbar__crumb { display: flex; align-items: center; gap: 9px; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ea-topbar__crumb strong { color: var(--ea-ink); font-weight: 500; }
.ea-topbar__actions { display: flex; align-items: center; gap: 10px; flex: none; }
.ea-topbar__hint { color: var(--ea-muted); font-size: 12px; }
.ea-theme-toggle {
  min-height: 32px;
  padding: 5px 12px;
  border: 0;
  border-radius: var(--ea-radius-pill);
  color: var(--ea-ink);
  background: var(--ea-hover);
  font-size: 12px;
  cursor: pointer;
}
.ea-theme-toggle:hover { background: var(--ea-pressed); }
@media (max-width: 640px) {
  .ea-topbar { min-height: 48px; padding: 0 16px; }
  .ea-topbar__hint { display: none; }
  .ea-theme-toggle { min-height: 40px; }
}
.platform-back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: max-content;
  min-height: 34px;
  padding: 6px 12px;
  border: 0;
  border-radius: var(--ea-radius-pill);
  color: var(--ea-action);
  background: var(--ea-action-soft);
  font-size: 12px;
  font-weight: 600;
  line-height: 20px;
  text-decoration: none;
  white-space: nowrap;
  transition: background .16s var(--ea-ease),transform .1s var(--ea-ease);
}
.platform-back:hover { color: var(--ea-action-hover); background: var(--ea-selection); }
.platform-back:active { transform: scale(.975); }
@media (max-width:640px),(pointer:coarse) { .platform-back { min-height: 44px; } }

/* Shared Apple shell controls: canonical homepage geometry. */

.ea-platform-logo {
  display: block;
  width: 133px;
  height: 41px;
  flex: none;
  background: var(--ea-ink);
  -webkit-mask: url("data:image/svg+xml;base64,") left center / contain no-repeat;
  mask: url("data:image/svg+xml;base64,") left center / contain no-repeat;
}
.ea-theme-toggle { display: inline-flex; align-items: center; justify-content: center; min-height: 32px; padding: 0; background: transparent; border: 0; border-radius: 100px; }
.ea-theme-toggle:hover { background: transparent; }
.ea-theme-track { position: relative; display: grid; grid-template-columns: 1fr 1fr; align-items: center; justify-items: center; width: 62px; height: 30px; background: var(--ea-hover); border-radius: 100px; }
.ea-theme-thumb { position: absolute; left: 3px; top: 3px; width: 26px; height: 24px; border-radius: 100px; background: var(--ea-base); box-shadow: 0 1px 3px rgba(0,0,0,.18); transition: transform .3s var(--ea-ease); }
.ea-theme-day,.ea-theme-night { position: relative; z-index: 1; display: grid; place-items: center; color: var(--ea-muted); }
